import React from 'react';
import { Gauge, CheckCircle2, AlertOctagon, Zap, Award, Layers } from 'lucide-react';

const CircleGauge = ({ value, max = 100, color = '#2563EB', size = 56, strokeWidth = 5.5, label, suffix = '%' }) => {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const pct = Math.min(100, Math.max(0, (value / max) * 100));
  const strokeDashoffset = circumference - (pct / 100) * circumference;

  return (
    <div style={{ position: 'relative', width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
      <svg width={size} height={size} style={{ transform: 'rotate(-90deg)' }}>
        <circle cx={size / 2} cy={size / 2} r={radius} stroke="#E2E8F0" strokeWidth={strokeWidth} fill="transparent" />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke={color}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          fill="transparent"
          style={{ transition: 'stroke-dashoffset 0.6s ease' }}
        />
      </svg>
      <span style={{ position: 'absolute', fontSize: '0.7rem', fontWeight: '900', color: '#0F172A' }}>
        {label !== undefined ? label : `${value}${suffix}`}
      </span>
    </div>
  );
};

const ProductionMonitoringCard = () => {
  return (
    <div className="glass-card" style={{ padding: '1.5rem', marginBottom: '1.75rem', background: '#ffffff', borderRadius: '14px', border: '1px solid #E2E8F0' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
        <div>
          <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Gauge size={20} style={{ color: 'var(--accent-primary)' }} /> Live Production Output & Quality Monitoring
          </h3>
          <p style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: '600', marginTop: '2px' }}>
            Weaving Loom Output Yield, Defect Rates, and Line Speeds
          </p>
        </div>
        <span className="badge badge-running" style={{ fontWeight: '800' }}>Shift Target: 16,000 M</span>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(210px, 1fr))', gap: '1.1rem' }}>
        {/* TODAY'S PRODUCTION */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>TODAY'S PRODUCTION</div>
            <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#0F172A', marginTop: '2px' }}>14,250 <span style={{ fontSize: '0.78rem' }}>m</span></div>
            <div style={{ fontSize: '0.72rem', color: '#16A34A', marginTop: '3px', fontWeight: '800' }}>89.1% Target Progress</div>
          </div>
          <CircleGauge value={89.1} color="#2563EB" />
        </div>

        {/* TARGET PRODUCTION */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>TARGET PRODUCTION</div>
            <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#0F172A', marginTop: '2px' }}>16,000 <span style={{ fontSize: '0.78rem' }}>m</span></div>
            <div style={{ fontSize: '0.72rem', color: '#64748B', marginTop: '3px', fontWeight: '700' }}>Remaining: 1,750 M</div>
          </div>
          <CircleGauge value={100} color="#0EA5E9" label="100%" />
        </div>

        {/* MACHINE EFFICIENCY */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>MACHINE EFFICIENCY</div>
            <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#2563EB', marginTop: '2px' }}>96.4%</div>
            <div style={{ fontSize: '0.72rem', color: '#16A34A', marginTop: '3px', fontWeight: '800' }}>Optimal Grade A</div>
          </div>
          <CircleGauge value={96.4} color="#16A34A" />
        </div>

        {/* FABRIC QUALITY */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>FABRIC QUALITY</div>
            <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#059669', marginTop: '2px' }}>99.1%</div>
            <div style={{ fontSize: '0.72rem', color: '#059669', marginTop: '3px', fontWeight: '800' }}>First-Choice Standard</div>
          </div>
          <CircleGauge value={99.1} color="#059669" />
        </div>

        {/* REJECTED FABRIC */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>REJECTED FABRIC</div>
            <div style={{ fontSize: '1.45rem', fontWeight: '900', color: '#EA580C', marginTop: '2px' }}>0.9%</div>
            <div style={{ fontSize: '0.72rem', color: '#EA580C', marginTop: '3px', fontWeight: '800' }}>Below 1.5% Limit</div>
          </div>
          <CircleGauge value={0.9} max={5} color="#EA580C" label="0.9%" />
